sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        // Parse request body — try multiple approaches for compatibility
        var body;
        try {
            body = request.body.data;
        } catch (e1) {
            try {
                body = JSON.parse(request.body.dataString);
            } catch (e2) {
                body = {};
            }
        }
        if (!body) { body = {}; }

        var sessionId      = body.session_id      ? body.session_id + ''      : 'default';
        var prompt         = body.prompt           ? body.prompt + ''          : '';
        var model          = body.model            ? body.model + ''           : '';
        var systemPrompt   = body.system_prompt    ? body.system_prompt + ''   : '';
        var prefill        = body.prefill          ? body.prefill + ''         : '';
        var stopSeqsRaw    = body.stop_sequences   ? body.stop_sequences + ''  : '';
        var maxTokensRaw   = body.max_tokens       ? body.max_tokens + ''      : '';
        var temperatureRaw = body.temperature      ? body.temperature + ''     : '';

        if (!prompt) {
            response.setStatus(400);
            response.setBody({ error: 'prompt is required' });
            return;
        }

        // Optional per-request max_tokens override
        var maxTokens = 0;
        if (maxTokensRaw) {
            var parsedTok = parseInt(maxTokensRaw, 10);
            if (!isNaN(parsedTok) && parsedTok > 0) { maxTokens = parsedTok; }
        }

        // Optional temperature override (0.0 – 1.0)
        var temperature = null;
        if (temperatureRaw !== '') {
            var parsedTemp = parseFloat(temperatureRaw);
            if (!isNaN(parsedTemp) && parsedTemp >= 0 && parsedTemp <= 1) { temperature = parsedTemp; }
        }

        // Load persistent conversation history from the message table
        var mgr      = new x_146833_claudec_0.ClaudeConversationManager();
        var messages = mgr.load_messages(sessionId);

        // Add the new user message (add_user_message handles plain strings)
        mgr.add_user_message(messages, prompt);

        // Parse stop sequences (comma-separated string)
        var stopArr = [];
        if (stopSeqsRaw) {
            var parts = (stopSeqsRaw).split(',');
            for (var i = 0; i < parts.length; i++) {
                var s = parts[i].trim();
                if (s) { stopArr.push(s); }
            }
        }

        // Call Claude via the ClaudeConnector script include (agentic tool-use loop)
        var connector;
        try {
            connector = new x_146833_claudec_0.ClaudeConnector();
        } catch (e) {
            response.setStatus(500);
            response.setBody({ error: 'Failed to load ClaudeConnector: ' + e.toString() });
            return;
        }

        var callOpts = {
            model:          model,
            system_prompt:  systemPrompt,
            stop_sequences: stopArr,
            // Logging context for ClaudeRequestLogger staging table
            session_id:     sessionId,
            prompt:         prompt
        };
        if (maxTokens > 0)       { callOpts.max_tokens  = maxTokens; }
        if (temperature != null) { callOpts.temperature = temperature; }

        var result;
        try {
            result = connector.chatWithTools(messages, callOpts);
        } catch (e) {
            response.setStatus(500);
            response.setBody({ error: 'ClaudeConnector.chatWithTools() threw: ' + e.toString() });
            return;
        }

        if (result && result.success) {
            response.setBody({
                text:         result.text,
                model:        result.model,
                inputTokens:  result.inputTokens,
                outputTokens: result.outputTokens,
                totalTokens:  (result.inputTokens || 0) + (result.outputTokens || 0),
                toolRounds:   result.toolRounds || 0
            });
        } else {
            response.setStatus(500);
            response.setBody({ error: (result && result.error) ? result.error : 'Unknown error from ClaudeConnector' });
        }
    } catch (ex) {
        response.setStatus(500);
        response.setBody({ error: 'Unhandled exception: ' + ex.toString() });
    }
})(request, response);
